Q: Material UI TextField disable Browser autoComplete A: <p>As of today, none of the options presented below have helped me, so I decided to cheat:</p>
<pre><code>import {
  TextField,
  Tooltip,
  IconButton as MUButton,
  TextFieldProps,
} from 'e100-react-components-ts'; // That is just our wrapper for MUI 7+ version 
import useBoolState from '@common/hooks/useBoolState';

import IconButton from './IconButton';
import PasswordValidationRulesIcon from '../PasswordValidationRulesIcon';
import { EMPTY_STRING } from '@/common/constants';

interface Props extends Omit&lt;TextFieldProps, 'ref' | 'onChange'&gt; {
  value: string;
  onChange?: TextFieldProps['onChange'];
  placeholder?: string;
  fullWidth?: boolean;
  error?: boolean;
  helperText?: string;
  tooltipMessage?: string;
  withInfo?: boolean;
  withClear?: boolean;
  disableBrowserAutofill?: boolean;
}

const PasswordTextField = (props: Props) =&gt; {
  const {
    value,
    onChange = () =&gt; {},
    placeholder,
    fullWidth = false,
    error = false,
    helperText = null,
    tooltipMessage = '',
    withInfo = false,
    withClear = false,
    autoComplete = 'off',
    disableBrowserAutofill = false,
    ...rest
  } = props;
  const [isPasswordType, onToggleIsPasswordType] = useBoolState(true);

  const isHackSupported =
    typeof document !== 'undefined' &amp;&amp;
    'WebkitTextSecurity' in document.body.style;
  const isHackActive =
    disableBrowserAutofill &amp;&amp; isPasswordType &amp;&amp; isHackSupported;
  const typeValue = isHackActive
    ? 'text'
    : isPasswordType
      ? 'password'
      : 'text';

  const inputPropsExt = (rest as any).inputProps || {};

  return (
    &lt;Tooltip
      title={tooltipMessage}
      open={!!tooltipMessage}
      placement='bottom-start'
    &gt;
      &lt;TextField
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        fullWidth={fullWidth}
        type={typeValue}
        error={error}
        helperText={helperText || EMPTY_STRING}
        autoComplete={disableBrowserAutofill ? 'off' : autoComplete}
        {...rest}
        inputProps={{
          ...inputPropsExt,
          ...(isHackActive
            ? { style: { ...inputPropsExt.style, WebkitTextSecurity: 'disc' } }
            : {}),
        }}
        InputProps={{
          endAdornment: (
            &lt;&gt;
              {withInfo &amp;&amp; &lt;PasswordValidationRulesIcon /&gt;}
              &lt;IconButton
                disabled={!value}
                isPasswordType={isPasswordType}
                onToggleIsPasswordType={onToggleIsPasswordType}
              /&gt;
              {withClear &amp;&amp; (
                &lt;MUButton
                  kind={'close'}
                  onClick={() =&gt; onChange({ target: { value: '' } } as any)}
                /&gt;
              )}
            &lt;/&gt;
          ),
        }}
      /&gt;
    &lt;/Tooltip&gt;
  );
};

export default PasswordTextField;
</code></pre>
